// Misst title/description im gerenderten HTML
const base = 'http://localhost:3100';
const paths = process.argv.slice(2);
const dec = s => s.replace(/&amp;/g,'&').replace(/&quot;/g,'"').replace(/&#x27;/g,"'").replace(/&#39;/g,"'").replace(/&lt;/g,'<').replace(/&gt;/g,'>').replace(/&#xFC;/gi,'ü');
for (const p of paths) {
  try {
    const r = await fetch(base + p, { redirect: 'manual' });
    if (r.status !== 200) { console.log(`${p}\tSTATUS ${r.status}`); continue; }
    const html = await r.text();
    const t = html.match(/<title[^>]*>([^<]*)<\/title>/);
    const d = html.match(/<meta name="description" content="([^"]*)"/);
    const title = t ? dec(t[1]) : '';
    const desc = d ? dec(d[1]) : '';
    const h1 = (html.match(/<h1[\s>]/g) || []).length;
    const robots = (html.match(/<meta name="robots" content="([^"]*)"/) || [])[1] || '-';
    const canon = (html.match(/<link rel="canonical" href="([^"]*)"/) || [])[1] || '-';
    const flagT = title.length > 60 ? ' !T' : '';
    const flagD = (desc.length < 138 || desc.length > 160) ? ' !D' : '';
    console.log(`${p}\tT=${title.length}${flagT}\tD=${desc.length}${flagD}\th1=${h1}\trobots=${robots}\tcanon=${canon}`);
    console.log(`   title: ${title}`);
    console.log(`   desc : ${desc}`);
  } catch (e) { console.log(`${p}\tFEHLER ${e.message}`); }
}

